{{
  config(
    materialized='incremental',
    incremental_strategy='merge',
    unique_key='event_id',
    partition_by={'field': 'event_date', 'data_type': 'date'},
    cluster_by=['event_date'],
    on_schema_change='append_new_columns'
  )
}}

SELECT
  event_id,
  event_date,
  user_id,
  event_type,
  payload,
  updated_at
FROM {{ source('raw', 'events') }}

{% if is_incremental() %}
  -- Reprocess a trailing window to catch late-arriving updates,
  -- not just rows strictly newer than the last max watermark
  WHERE event_date >= DATEADD(day, -4, (SELECT MAX(event_date) FROM {{ this }}))
{% endif %}

variable "environment" {
  type        = string
  description = "dev, test, or prod"
  validation {
    condition     = contains(["dev", "test", "prod"], var.environment)
    error_message = "environment must be one of dev, test, prod."
  }
}

variable "team_owner" {
  type = string
}

variable "replication_type" {
  type    = string
  default = "LRS"  # prod overrides to GRS via tfvars, not hardcoded here
}

locals {
  common_tags = {
    environment = var.environment
    owner       = var.team_owner
    managed_by  = "terraform"
    cost_center = "data-platform-${var.environment}"
  }
  storage_name = "stdp${var.environment}${substr(md5(var.team_owner), 0, 6)}"
}

resource "azurerm_storage_account" "landing" {
  name                     = local.storage_name
  resource_group_name      = var.resource_group_name
  location                 = var.location
  account_tier             = var.environment == "prod" ? "Standard" : "Standard"
  account_replication_type = var.replication_type
  tags                     = local.common_tags
}

resource "azurerm_user_assigned_identity" "landing_identity" {
  name                = "id-landing-${var.environment}"
  resource_group_name = var.resource_group_name
  location            = var.location
  tags                = local.common_tags
}

# Least-privilege: scoped to this storage account only, not subscription-wide
resource "azurerm_role_assignment" "landing_rw" {
  scope                = azurerm_storage_account.landing.id
  role_definition_name = "Storage Blob Data Contributor"
  principal_id          = azurerm_user_assigned_identity.landing_identity.principal_id
}

output "storage_account_id" {
  value = azurerm_storage_account.landing.id
}

output "identity_client_id" {
  value = azurerm_user_assigned_identity.landing_identity.client_id
}

from airflow.decorators import dag, task
from airflow.sensors.base import PokeReturnValue
from airflow.providers.docker.operators.docker import DockerOperator
from airflow.exceptions import AirflowFailException
from pendulum import datetime

default_args = {
    "retries": 2,
    "retry_delay": 300,  # seconds; bounded, not indefinite
    "on_failure_callback": None,  # wired to the alert task below via trigger_rule instead
}

@dag(
    dag_id="ingest_then_dbt_build",
    schedule="0 6 * * *",
    start_date=datetime(2026, 11, 1),
    catchup=False,
    default_args=default_args,
    tags=["dbt", "cross-platform", "production"],
)
def ingest_then_dbt_build():

    @task.sensor(poke_interval=60, timeout=3600, mode="reschedule")
    def wait_for_ingestion() -> PokeReturnValue:
        status = check_sync_connector_status("orders_connector")
        if status == "failed":
            raise AirflowFailException("Upstream ingestion connector failed; not retrying blindly")
        return PokeReturnValue(is_done=(status == "succeeded"))

    @task
    def run_dbt_build():
        import subprocess
        result = subprocess.run(
            ["dbt", "build", "--select", "source:raw.orders+"],
            capture_output=True, text=True,
        )
        if result.returncode != 0:
            raise AirflowFailException(f"dbt build failed:\n{result.stdout}\n{result.stderr}")

    @task(trigger_rule="one_failed")
    def alert_on_failure():
        send_pagerduty_alert(
            summary="ingest_then_dbt_build pipeline failed",
            severity="warning",
        )

    ingestion_done = wait_for_ingestion()
    build = run_dbt_build()
    ingestion_done >> build
    alert_on_failure()

ingest_then_dbt_build()

CREATE OR ALTER PROCEDURE dbo.usp_AdjustInventory
  @ProductId INT,
  @Delta INT
AS
BEGIN
  DECLARE @Attempt INT = 0;
  DECLARE @MaxAttempts INT = 3;

  WHILE @Attempt < @MaxAttempts
  BEGIN
    BEGIN TRY
      SET TRANSACTION ISOLATION LEVEL SNAPSHOT;
      BEGIN TRAN;

        -- Re-read current state fresh on every attempt; do not reuse a stale value
        DECLARE @CurrentQty INT;
        SELECT @CurrentQty = Quantity FROM dbo.Inventory WHERE ProductId = @ProductId;

        IF @CurrentQty + @Delta < 0
        BEGIN
          ROLLBACK TRAN;
          THROW 51000, 'Insufficient inventory', 1;
        END

        UPDATE dbo.Inventory
          SET Quantity = @CurrentQty + @Delta
          WHERE ProductId = @ProductId;

      COMMIT TRAN;
      BREAK;  -- success, exit retry loop
    END TRY
    BEGIN CATCH
      IF XACT_STATE() <> 0 ROLLBACK TRAN;
      IF ERROR_NUMBER() = 3960
      BEGIN
        SET @Attempt += 1;
        IF @Attempt >= @MaxAttempts
          THROW;
        WAITFOR DELAY '00:00:00.100';
        CONTINUE;  -- retry: loop back and re-read @CurrentQty fresh
      END
      ELSE
        THROW;  -- not a conflict error; do not retry blindly
    END CATCH
  END
END
